class Env {
    final Env? parent;
    final frame = <String, Object>{
    Env([this.parent]);
    Env find(String n){
        for (Env? e = this; e != null; e = e.parent){
            if (e.frame.containsKey(n))return e;
    Object get(String n){
        final v = find(n).frame[n]!;
        if (identical(v, uninitialized))throw LispError('uninitialized variable: $n');
        return v;
class Procedure {
